function watchTenkaichi(done){const pool=tenkaichiPick(null,(Date.now()%2147483646)+1);if(pool.length<48){done();return}
 let s=(Date.now()%2147483646)+1;const rnd=()=>{s=(Math.imul(s,1103515245)+12345)>>>0;return s/4294967296;};
 const shuffled=[...pool];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}
 const groups=Array.from({length:12},(_,i)=>shuffled.slice(i*4,i*4+4).map(e=>e.id));
 const runLike={mode:'grand',entrants:pool,groups,gResults:[],koResults:[]};
 const nameOf=id=>pool.find(e=>e.id===id)?.name??id;
 const jobs=[];
 groups.forEach(g=>{for(let md=0;md<3;md++)for(const [a,b] of rrPairs(g,md))jobs.push(()=>{runLike.gResults.push({a,b,w:simCupMatch(runLike,a,b,Math.floor(rnd()*2147483647))});});});
 let idx=0,ko=null;const koRounds=[];
 const total=jobs.length+31;
 const step=()=>{
  let n=0;
  while(idx<jobs.length&&n<4){jobs[idx++]();n++;}
  if(idx>=jobs.length){
   if(!ko)ko=tenkaichiQualifiers(runLike);
   if(ko.length>1){const res=[],win=[];for(let i=0;i<ko.length;i+=2){const a=ko[i],b=ko[i+1];const w=simCupMatch(runLike,a,b,Math.floor(rnd()*2147483647))??(entrantLevel(runLike,a)>=entrantLevel(runLike,b)?a:b);res.push({a:nameOf(a),b:nameOf(b),winner:nameOf(w)});win.push(w);}koRounds.push(res);ko=win;}
   if(ko.length>1){setTimeout(step,0);return;}
   const champ=pool.find(e=>e.id===ko[0]);
   ui.tenkaichiWatch={champion:champ.name,championFrom:champ.from,qualifiers:tenkaichiQualifiers(runLike).map(nameOf),koRounds};
   remember();done();return;
  }
  const el=document.querySelector('#fight-loading div');if(el)el.textContent='大会を集計しています…（'+Math.min(idx,total)+'/'+total+'）';
  setTimeout(step,0);};
 step();}
function renderTournamentRecords(){const career=state.cupCareer;screen('大会の戦績',`${meta()}<dl class="facts"><div><dt>大会の試合数</dt><dd>${career.completed}</dd></div><div><dt>優勝した杯</dt><dd>${career.champions.length}種目</dd></div></dl>${career.champions.length?`<p class="small">優勝：${career.champions.map(id=>esc(CUP_CATALOG[id]?.name??id)).join('、')}</p>`:'<p class="small muted">まだ優勝した杯はありません。</p>'}${career.eventEntries.length?`<p class="small">大会イベント参加：${career.eventEntries.map(e=>esc(CUP_CATALOG[e.mode]?.name??TOURNAMENT_CATALOG[e.mode]?.name??e.mode)).join('、')}</p>`:''}`,btn('tournament','大会へ','','primary')+btn('records','旅の記録へ戻る','','quiet'),'TOURNAMENT RECORD');}
