const LEVELUP_CSS='.levelup-overlay{position:fixed;inset:0;z-index:300;display:flex;align-items:center;justify-content:center;overflow:hidden;background:radial-gradient(ellipse at center,rgba(24,19,4,.30) 0%,rgba(6,9,12,.80) 78%);opacity:1;transition:opacity .35s ease}'
+'.levelup-overlay.levelup-out{opacity:0}'
+'.levelup-rays{position:absolute;left:50%;top:50%;width:170vmax;height:170vmax;transform:translate(-50%,-50%);border-radius:50%;background:repeating-conic-gradient(from 0deg,rgba(245,197,66,.13) 0deg 9deg,rgba(245,197,66,0) 9deg 18deg);animation:levelupSpin 18s linear infinite;pointer-events:none}'
+'@keyframes levelupSpin{to{transform:translate(-50%,-50%) rotate(360deg)}}'
+'.levelup-card{position:relative;text-align:center;padding:24px;animation:levelupPop .45s cubic-bezier(.2,1.35,.35,1) both}'
+'@keyframes levelupPop{0%{transform:scale(.55);opacity:0}100%{transform:scale(1);opacity:1}}'
+'.levelup-title{margin:0;font-size:58px;line-height:1.05;font-weight:800;letter-spacing:.05em;color:#ffd968;text-shadow:0 0 26px rgba(245,197,66,.85),0 0 60px rgba(245,197,66,.45),0 3px 0 #8a6d1f,0 6px 18px rgba(0,0,0,.6)}'
+'.levelup-level{margin:10px 0 0;font-size:36px;font-weight:700;color:#fff;text-shadow:0 0 16px rgba(255,217,104,.65),0 2px 10px rgba(0,0,0,.7)}'
+'.levelup-level small{font-size:20px;color:#ffe9a8;margin-right:2px}'
+'.levelup-points{display:inline-block;margin-top:14px;padding:6px 16px;border:1px solid rgba(255,217,104,.85);border-radius:999px;background:rgba(30,24,6,.72);color:#ffd968;font-size:17px;font-weight:700;letter-spacing:.04em}'
+'.levelup-spark{position:absolute;width:7px;height:7px;border-radius:50%;background:#ffe9a8;box-shadow:0 0 10px 2px rgba(245,197,66,.75);animation:levelupTwinkle 1.15s ease-in-out infinite;pointer-events:none}'
+'@keyframes levelupTwinkle{0%,100%{transform:scale(.45);opacity:.25}50%{transform:scale(1.15);opacity:1}}'
+'@media (prefers-reduced-motion:reduce){.levelup-rays,.levelup-card,.levelup-spark{animation:none}}';
function ensureLevelupCss(){if(document.querySelector('#levelup-style'))return;const st=document.createElement('style');st.id='levelup-style';st.textContent=LEVELUP_CSS;document.head.appendChild(st);}
let levelupCelebratedKey=null;
function celebrateLevelUp(key,level,points){
 if(levelupCelebratedKey===key)return;levelupCelebratedKey=key;
 ensureLevelupCss();
 document.querySelector('.levelup-overlay')?.remove();
 const el=document.createElement('div');el.className='levelup-overlay';el.setAttribute('role','status');el.setAttribute('aria-label','レベルアップ。レベル'+level+'になりました。');
 const sparks=[[8,16,0],[88,12,.25],[14,82,.5],[84,78,.15],[50,4,.65],[28,94,.35],[70,92,.55],[95,45,.45]].map(([x,y,d])=>`<i class="levelup-spark" style="left:${x}%;top:${y}%;animation-delay:${d}s"></i>`).join('');
 el.innerHTML=`<div class="levelup-rays"></div>${sparks}<div class="levelup-card"><p class="levelup-title">LEVEL UP!</p><p class="levelup-level"><small>Lv.</small>${level}</p>${points?`<p><span class="levelup-points">強化ポイント +${points} pt</span></p>`:''}</div>`;
 document.body.appendChild(el);
 let gone=false;const dismiss=()=>{if(gone)return;gone=true;el.classList.add('levelup-out');setTimeout(()=>el.remove(),380);};
 el.addEventListener('click',dismiss);
 setTimeout(dismiss,3000);
}
function screen(title,content,actions,eyebrow=''){
 const view=resetOpen?'reset':ui.view,navAction=({home:'title',hub:'home',equipment:'equipment-done',abilities:'ability-back',styles:'style-cancel',result:'hub',appearance:'appearance-cancel','local-training':'hub','local-training-story':'training-skip',menu:'hub','fight-records':'records',battle:'pause','opponent-list':'back',candidates:'equipment','skill-detail':'detail-back',pause:'resume','guest-settings':'title'})[view]||'back',labels={home:'HOME',hub:'FIGHT',equipment:'EQUIPMENT',abilities:'GROWTH',battle:'AUTO BATTLE',result:'RESULT','fighter-settings':'FIGHTER'},isTitle=['welcome','title'].includes(view);
 app.innerHTML=`<section class="game-screen ${isTitle?'title-screen':''}" data-screen="${esc(view)}">${isTitle?'':`<div class="topline">${view==='battle'?'':btn(navAction,'‹ 戻る','','nav-back')}<span class="brand-small">WFJ / ${labels[view]||'JOURNEY'}</span>${state&&state.abilities.confirmed&&(!battle||battle.done&&result)&&!demo&&view!=='home'?btn('home','ホーム','','nav-home'):''}</div>`}<div class="screen-heading">${eyebrow?`<p class="eyebrow">${esc(eyebrow)}</p>`:''}<h1>${title}</h1></div><div class="screen-content">${storageBlocked?'<p role="alert">記録保護のため更新を止めています。再読込、または対応するブラウザーで確認してください。</p>':''}${content}</div><nav class="screen-actions" aria-label="画面の操作">${actions}</nav></section>`;window.scrollTo?.(0,0);ensureHubCss();ensureFighterCss();markTutorialControls()
}
function go(view,patch={},replace=false){if(!replace)trail.push({...ui,dojo:{...ui.dojo},opponentSession,opponentEpoch});Object.assign(ui,patch,{view});remember();if(window.history){const snapshot={view:ui.view,countryPage:ui.countryPage,mapRegion:ui.mapRegion,mapCountry:ui.mapCountry,recordsCountry:ui.recordsCountry,mapStart:ui.mapStart,dojo:{...ui.dojo},slot:ui.slot,page:ui.page,skill:ui.skill,tab:ui.tab,equipReturn:ui.equipReturn,detailReturn:ui.detailReturn,opponentSession,opponentEpoch};window.history[replace?'replaceState':'pushState']({wfjUI:snapshot},'','#'+view)}render()}
function returnToMap(){const view=state?'world':'countries';if(trail.at(-1)?.view===view){const selected=ui.mapCountry;ui={...navigationUI(trail.pop()),mapCountry:selected};remember();render()}else go(view,{},true)}
function back(){if(ui.view==='country-detail'){returnToMap();return}if(ui.view==='appearance'){cancelAppearance();return}if(ui.view==='abilities'){saveAllocation(true);return}if(resetOpen){closeReset();return}if(battle&&!battle.done)return;if(demo){if(ui.view==='skill-detail'){demo.paused=false;go('demo',{},true);return}if(demo.acquired){demo=null;go(ui.result?'result':'hub',{},true)}else{const returnView=demo.returnView,origin=demo.originDetails;demo=null;ui.detailReturn=origin||'candidates';go(returnView||'skill-detail',{},true)}return}const prior=trail.pop();if(prior){ui=navigationUI(prior);remember();render()}else go(state?'hub':'welcome',{},true)}
function meta(){return `<div class="mini-hud"><strong>${esc(country().name)}</strong><span>${state.money}G</span><span>${RANKS[journeyRank(state)]}</span></div>`}
function render(){if(resetOpen){renderReset();return}if(battle?.done&&!result&&state?.pendingResult){ui.view='battle';renderBattle();return}if(!state){if(['start-japan','countries','country-detail'].includes(ui.view))renderJapanStart();else if(ui.view==='guest-settings')renderGuestSettings();else renderWelcome();return}if(tutorialActive(state)){const g=tutorialGate(state);if(g&&!g.views.includes(ui.view)&&ui.view!=='battle')ui.view=g.view;}advanceTutorialSkill();if(ui.view==='title'){renderWelcome();return}if(ui.view==='clear'&&!completeJourney(state))ui.view='world';if(!state.abilities.confirmed&&ui.view!=='result'&&ui.view!=='battle'&&ui.view!=='abilities'){ui.abilityReturn=['welcome','countries'].includes(ui.view)?'hub':ui.view;ui.view='abilities';}if(!['home','fighter-settings','abilities','hub','opponent-list','equipment','candidates','skill-detail','demo','battle','pause','result','received','world','menu','records','fight-records','guide','clear','styles','country-detail','appearance','local-training','local-training-story','tournament','tournament-records'].includes(ui.view))ui.view='hub';if(ui.view==='home')return renderHome();if(ui.view==='fighter-settings')return renderFighterSettings();if(ui.view==='local-training')return renderLocalTraining();if(ui.view==='local-training-story')return renderTrainingStory();if(ui.view==='tournament')return renderTournament();if(ui.view==='tournament-records')return renderTournamentRecords();if(ui.view==='appearance')return renderAppearance();if(ui.view==='country-detail')return renderCountryDetail(false);if(ui.view==='styles')return renderStyles();if(ui.view==='abilities')return renderAbilities();if(ui.view==='demo'&&demo)return renderDemo();if(ui.view==='battle'&&battle)return renderBattle();if(ui.view==='pause'&&battle&&!battle.done)return renderPause();if(ui.view==='result'&&ui.result)return renderResult();if(ui.view==='received'&&ui.result)return renderReceived();if(ui.view==='equipment')return renderEquipment();if(ui.view==='candidates'&&ui.slot)return renderCandidates();if(ui.view==='skill-detail'&&tech(ui.skill))return renderSkillDetail();if(ui.view==='opponent-list')return renderOpponentList();if(ui.view==='world')return renderCountries(false);if(ui.view==='menu')return renderMenu();if(ui.view==='records')return renderRecords();if(ui.view==='fight-records')return renderFightRecords();if(ui.view==='guide')return renderGuide();if(ui.view==='clear')return renderClear();ui.view='hub';renderHub()}
function renderAbilities(){
 const a=state.abilities;let d=ui.abilityDraft;if(!d||pointTotal(d)===null||!validPoints(Object.fromEntries(Object.keys(ABILITY_NAMES).map(k=>[k,a.spent[k]+d[k]])))||pointTotal(d)>unspent(a))ui.abilityDraft=d={power:0,speed:0,stamina:0};
 const remain=unspent(a)-Object.values(d).reduce((n,v)=>n+v,0),totals=Object.fromEntries(Object.keys(ABILITY_NAMES).map(k=>[k,a.spent[k]+d[k]])),v=abilityStats(totals);
 screen('自分の強さを選ぶ',`${guideHtml()}<div class="ability-banner"><img src="${ART.travel.src}" alt="旅先へ続く道"><div class="point-total"><div><p>未使用ポイント</p><b>${remain}<span>pt</span></b></div><p>Lv.${a.level} · 次まで${experienceStatus(state).remaining}経験<br>${a.confirmed?'強化ポイント':'最初の10ポイント'}</p></div></div><div class="ability-list">${Object.keys(ABILITY_NAMES).map(k=>`<article class="ability-row ${d[k]?'changed':''}"><div class="ability-heading"><strong>${ABILITY_NAMES[k]}</strong><div class="stepper">${btn('ability-minus','−',k,'quiet',d[k]===0)}<b>${totals[k]}</b>${btn('ability-plus','＋',k,'quiet',remain===0)}</div></div><p class="ability-full">${k==='power'?'1ptで基準威力 +'+Math.round(ABILITY_RULES.powerPerPoint*100)+'%<br>打撃倍率 <b>'+Math.round(v.power*100)+'%</b>（未配分'+Math.round(ABILITY_RULES.basePower*100)+'%）':k==='speed'?'20ptまでは1ptで動作 +6% / 移動 +12%。21ptから伸びが緩やかになります。<br>動作 <b>+'+Number(((v.speed-1)*100).toFixed(1))+'%</b> / 移動 <b>+'+Number((speedBonuses(totals.speed).movement*100).toFixed(1))+'%</b>':'1ptでHP +'+ABILITY_RULES.hpPerStaminaPoint+' / SP +'+ABILITY_RULES.staminaPerPoint+'<br>最大HP <b>'+v.maxHp+'</b> / SP <b>'+v.maxStamina+'</b>'}</p><p class="ability-compact">${k==='power'?'打撃 '+Math.round(v.power*100)+'% / 1pt +'+Math.round(ABILITY_RULES.powerPerPoint*100)+'%':k==='speed'?'動作 +'+Number(((v.speed-1)*100).toFixed(1))+'% / 移動 +'+Number((speedBonuses(totals.speed).movement*100).toFixed(1))+'%（20pt超は緩やかに成長）':'HP '+v.maxHp+' / SP '+v.maxStamina+'（1pt +'+ABILITY_RULES.hpPerStaminaPoint+' / +'+ABILITY_RULES.staminaPerPoint+'）'}</p></article>`).join('')}</div><p class="ability-rules small">配分上限なし（所持ptの範囲）。強敵への勝利ほど経験値が増え、レベルが高いほど必要経験値も増えます。修行と大会優勝でも成長。Lv+1で自由配分1pt。確定後の振り直し不可。</p>`,btn('ability-confirm','この配分で確定','','primary')+btn('ability-cancel','配分取消','','quiet')+btn('ability-back','戻る・未配分を保留','','quiet'),a.confirmed?'旅する拳士 / 能力配分':'初期10ポイントを自由に配分');
}
function advanceTutorialAllocation(){
 const tut=state.tutorial;if(!tut||tut.rule!==1)return;
 if(tut.step==='intro'){if(state.abilities.confirmed&&unspent(state.abilities)===0){const nx=structuredClone(state);nx.tutorial={...nx.tutorial,step:'fight1'};if(persist(nx))state=nx;}return;}
 if(tut.step==='allocate'&&tut.allocateBase!==null&&pointTotal(state.abilities.spent)>tut.allocateBase){const nx=structuredClone(state);nx.tutorial={...nx.tutorial,step:'fight3',allocateBase:null,rivalFreeze:rivalFreezeFor(nx.abilities.spent)};if(persist(nx))state=nx;}
}
// Skill step completion is state-based, not tied to one specific button:
// seeing the equipment (or candidate) screen during the skill step marks
// the visit, and returning to the hub or home afterwards completes the
// step — the guide promises completion on the way back, whichever back
// route the player takes (done button, header back, home button, slot
// detour). The old action-only wiring left players stuck when they came
// back through the candidate list or the hub board.
function markSkillVisited(){const tut=state?.tutorial;if(!tut||tut.rule!==1||tut.step!=='skill'||tut.skillVisitedEquip)return;const nx=structuredClone(state);nx.tutorial={...nx.tutorial,skillVisitedEquip:true};if(persist(nx))state=nx;}
function advanceTutorialSkill(){const tut=state?.tutorial;if(!tut||tut.rule!==1||tut.step!=='skill'||!tut.skillVisitedEquip)return;if(!['hub','home'].includes(ui.view))return;const nx=structuredClone(state);nx.tutorial={...nx.tutorial,step:'training'};if(persist(nx)){state=nx;ui.view='home';}}
function saveAllocation(hold=false){const previous=structuredClone(state),d=hold?{power:0,speed:0,stamina:0}:ui.abilityDraft;if(!allocateAbilities(state,d))return;if(!persist()){state=previous;toast('保存できないため確定を中止しました。');return}ui.abilityDraft={power:0,speed:0,stamina:0};advanceTutorialAllocation();go(ui.abilityReturn||'hub',{},true)}
function renderWelcome(){ui.view=state?'title':'welcome';screen('拳の旅路',`<div class="title-art"><img src="${sceneArt('street',state?.country??'jp').src}" alt="夕暮れの街"></div><p class="title-tag">街を越え、技をつなぐ。</p><div class="logo"><div class="letters">WF<em>J</em></div><h2>拳の旅路</h2><div class="english">WORLD FIGHTER JOURNEY</div></div><p class="title-sentence">知らない街で、<br>次の一人と向き合う。</p>${state?`<div class="resume muted">旅のつづき<strong>${esc(country().name)} · ${opponents(state).filter(o=>hasWon(state,o.id)).length} / ${courseCount(state.country)} 勝利</strong></div>`:''}${invalidSave?'<p role="alert" class="small">以前の記録を読めません。開始前にバックアップします。</p>':''}${storageBlocked?'<p role="alert">記録のバックアップができないため開始を止めています。</p>':''}`,(state?btn('continue','つづきから','','primary')+btn('reset','はじめから','','quiet')+btn('settings','設定','','quiet'):btn('choose-country','はじめから','','primary',storageBlocked)+btn('settings','設定','','quiet'))+'<a href="/motion-catalogue" class="button quiet" style="min-height:44px;display:flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #52616b;border-radius:8px;padding:10px">モーション一覧</a>','');}
function renderGuestSettings(){screen('設定',`<p>記録はこのブラウザーに自動保存されます。</p><p class="small">実際の対戦は自動で進みます。試合中に停止と再生速度を選べます。</p><p class="small">WORLD FIGHTER JOURNEY · v29</p>`,btn('title','タイトルへ戻る','','primary'));}
function renderJapanStart(){ui.view='start-japan';ui.mapStart=true;ui.mapCountry='jp';screen('日本から、旅をはじめる',`${artMarkup('street','japan-start-art')}<h2 class="start-country-name">日本 · 京都</h2><p>空手の街と道場で基本の技を学び、世界へ。</p><p class="small muted">最初の10ポイントを自由に配分できます。開始後は、対戦の途中でも世界地図から好きな渡航先を選べます。初めの出発は無料です。外見は「旅・能力」から変更できます。</p>`,btn('start','日本から出発する','jp','primary',storageBlocked)+btn('back','戻る','','quiet'),'旅の出発地は日本') }
function renderCountries(start){if(start)return renderJapanStart();const r=MAP_REGIONS[ui.mapRegion]??MAP_REGIONS.world;ui.mapStart=start;screen(start?'旅の出発地':'世界から選ぶ',`<p class="map-instruction">国をタップして詳細へ。${start?'出発は次の画面で確定します。':'渡航は確認ボタンで確定します。'}</p><div class="map-regions">${Object.entries(MAP_REGIONS).map(([id,v])=>btn('map-region',v.label,id,id===ui.mapRegion?'selected':'quiet')).join('')}</div><div class="world-map"><svg viewBox="${r.box.join(' ')}" preserveAspectRatio="none" aria-hidden="true"><image href="./assets/world-map.svg" width="1000" height="440"/></svg>${mapPins(ui.mapRegion).map(c=>{const d=countryDifficulty(state,c.id);return `<div class="map-anchor" style="left:${c.x}%;top:${c.y}%"><i></i><span class="map-leader" style="width:${Math.hypot(c.dx,c.dy)}px;transform:rotate(${Math.atan2(c.dy,c.dx)}rad)"></span></div><button data-action="country-detail" data-id="${c.id}" class="map-pin ${state?.country===c.id?'current':''}" style="left:clamp(23px,calc(${c.x}% + ${c.dx}px),calc(100% - 23px));top:clamp(23px,calc(${c.y}% + ${c.dy}px),calc(100% - 23px));transform:translate(-50%,-50%)" aria-label="${c.name}の詳細"><b>${c.id.toUpperCase()}</b>${ui.mapRegion==='world'?'':`<small>${d.label}</small>`}</button>`}).join('')}</div><p class="small muted">国コードの下は国全体の難度です。地域ボタンで拡大。</p>`,btn('back','戻る','','quiet'),start?'自由に開始国を選択':'選択しただけでは移動・支払はありません')}
function countryOutlook(c){const base=baseOpponents({country:c.id,journeyStart:'jp',wins:[]}),rivals=countryRivals(state,c,base),seen=new Set(),targets=[];
 base.forEach(o=>{if(!hasWon(state,o.id))nextDojoRewards(state,o.id).forEach(id=>{if(!seen.has(id)){seen.add(id);targets.push({id,via:'基礎'+(o.index+1)+'戦 · '+o.name+' Lv.'+opponentLevel(o)});}})});
 const courseLeft=base.filter(o=>!hasWon(state,o.id)).length;
 rivals.forEach(r=>(r.rewardMoves||[]).forEach(id=>{if(!state.known.includes(id)&&!seen.has(id)){seen.add(id);targets.push({id,via:'巡回'+r.ordinal+'戦目 · あと'+(courseLeft+rivals.filter(x=>x.ordinal<r.ordinal&&!hasWon(state,x.id)).length+1)+'勝'});}}));
 const next=base.find(o=>!hasWon(state,o.id)&&dojoUnlocked(state,o.id));return{targets,next:next?{name:next.name,level:opponentLevel(next)}:null,courseWon:base.filter(o=>hasWon(state,o.id)).length,courseCount:base.length,rivalWon:rivals.filter(r=>hasWon(state,r.id)).length,rivalCount:rivals.length};}
