function renderEquipment(){markSkillVisited();screen('試合の装備',`${guideHtml()}${artMarkup('equipment','equipment-banner')}<p class="small">${ui.equipReturn==='hub'?'相手：'+esc(selected().place):'枠を選んで技を入れ替えます。'}</p>${equipmentBoard()}`,btn('equipment-done',state.tutorial?.step==='skill'?'装備を確認した → 修行へ':ui.equipReturn==='hub'?'相手選択へ戻る':ui.equipReturn==='result'?'結果へ戻る':ui.equipReturn==='fighter-settings'?'拳士設定へ戻る':'相手選択へ戻る','','primary'),'打撃4・守備2・その他2') }
// Skill-picker UI (rig8): compact rows with the comparison facts inline
// (target / power / range / SP / windup from skillFacts, total at the right),
// the destination slot stated up top with a chip per slot, equipped skills
// shown with a 枠n badge and moved (never duplicated) on tap, and a demo
// preview band on top driven by the same demo renderer as the demo view.
// Focus (which skill the band shows) is switched by the small 見本 button on
// each row, so a row tap stays a single-purpose "set into this slot" action.
const CAND_UI_CSS='.game-screen[data-screen="candidates"]{height:100svh}'
+'.game-screen[data-screen="candidates"] .screen-content{display:flex;flex-direction:column;gap:8px;flex:1;min-height:0}'
