+'.cand-slot .no{font-size:10px;margin-right:3px;opacity:.75}'
+'.cand-slot.target{border-color:var(--amber);color:var(--amber);font-weight:700;background:rgba(229,181,99,.12)}'
+'.cand-preview{border:1px solid var(--line);background:#0d1a29;flex:none}'
