+'.cand-unavail{padding:12px;font-size:13px;margin:0}'
+'.cand-timing{display:flex;border-top:1px solid var(--line)}'
+'.cand-timing .seg{padding:5px 6px 6px;font-size:10.5px;color:var(--muted);white-space:nowrap;overflow:hidden;min-width:0}'
+'.cand-timing .seg b{color:var(--text);font-size:11px}'
