  if(g){tut.bonusGranted=true;tut.step='allocate';tut.allocateBase=pointTotal(next.abilities.spent);settled.xp+=missing;settled.levelUp=true;settled.abilityPoints=(settled.abilityPoints??0)+g.points;settled.level=next.abilities.level;settled.abilityProgress=next.abilities.progress;}
