document.addEventListener?.('keydown',e=>{if(resetOpen&&e.key==='Tab'){const buttons=[...app.querySelectorAll('.reset-dialog button')];if(buttons.length){e.preventDefault();const i=buttons.indexOf(document.activeElement);buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length].focus()}return}if(e.key==='Escape'){e.preventDefault();if(ui.view==='abilities'&&navigator.locks?.request)navigator.locks.request('world-fighter-main:'+REVIEW_SAVE_KEY,()=>back()).catch(()=>toast('記録を保存できませんでした。'));else back()}});
window.addEventListener?.('popstate',e=>{if(resetOpen){closeReset();return}if(battle&&!battle.done)return;if(demo){back();return}const saved=e.state?.wfjUI;if(saved){ui=navigationUI(saved);remember();render()}else if(ui.view==='abilities'&&navigator.locks?.request)navigator.locks.request('world-fighter-main:'+REVIEW_SAVE_KEY,()=>back()).catch(()=>toast('記録を保存できませんでした。'));else back()});
function loop(t){const dt=Math.min(.1,(t-last)/1000||0);last=t;if(ui.view==='local-training-story'&&(ui.trainingElapsed||0)<6){const prior=ui.trainingPhase;ui.trainingElapsed=Math.min(6,(ui.trainingElapsed||0)+dt);const next=ui.trainingElapsed<3?0:ui.trainingElapsed<6?1:2;if(next!==prior){remember();renderTrainingStory()}}if(demo){if(!demo.paused){demo.elapsed=(demo.elapsed+dt*.65*motionRate(player(state)))%skillDemoDuration(demo.ids[demo.index]);updateDemo()}}else if(battle&&!battle.done&&!paused){if(ticket?.rig?.mode==='director')applyTutorialDirector(battle,ticket);stepBattle(battle,dt*speed);updateBattle();if(battle.done)complete()}else if(battle?.done&&!result&&resultFlashAge<resultPresentationDuration(battle)){resultFlashAge=advanceResultPresentation(battle,resultFlashAge,dt,document.hidden);updateBattle();if(resultFlashAge+1e-9>=resultPresentationDuration(battle))complete()}if(ui.view==='candidates')updateCandPreview(dt);requestAnimationFrame(loop)}
if(SAVE_PROFILE.qa&&new URLSearchParams(location.search).get('large-text')==='1')document.documentElement.style.fontSize='200%';
if(SAVE_PROFILE.qa){const v=document.querySelector('.version');if(v)v.textContent='v29・検証用の別記録'}
if(state?.pendingResult){ticket=state.pendingResult.ticket;battle=state.pendingResult.battle;selectOpponentId(ticket.opponent.id);ui.view='battle'}
else if(state&&['result','received'].includes(ui.view)&&ui.result&&state.rewarded.includes(ui.result.id)){const o=opponents(state).find(o=>o.id===ui.result.opponentId||!ui.result.opponentId&&o.place===ui.result.place);if(o)selectOpponentId(o.id);}
if(state){if(ui.result&&!state.rewarded.includes(ui.result.id))ui.result=null;if(navigator.locks?.request)navigator.locks.request('world-fighter-main:'+REVIEW_SAVE_KEY,()=>{if(persist())remember();}).catch(()=>{storageBlocked=true;});else if(persist())remember();if(battle)renderBattle();else if((ui.view==='demo'||ui.view==='welcome')&&state.pendingDemos.length)openDemo([...state.pendingDemos],true);else if(ui.view==='demo'&&state.known.includes(ui.skill))openDemo(ui.skill);else{if(ui.view==='skill-detail'&&ui.detailReturn==='demo'&&state.known.includes(ui.skill)){const ids=state.pendingDemos.length?[...state.pendingDemos]:[ui.skill];demo={ids,index:0,elapsed:0,paused:true,acquired:state.pendingDemos.length>0,returnView:ui.demoReturn||'skill-detail',originDetails:ui.demoOrigin||'candidates',guardTarget:ids[0]==='jump'?'leg':'head'}}if(['welcome','countries','hub','home'].includes(ui.view))ui.view='title';render()}}else render();
requestAnimationFrame(loop);

warmSceneArt(()=>{if(!battle&&!demo)render()});

// Pre-upgrade tabs may still write the shared key. Keep their exact branch,
// repair from the committed journal and never merge or duplicate its rewards.
window.addEventListener?.('storage',e=>{if(e.key===linkedTournamentKey()||e.key===legacyTournamentKey()){if(state&&['home','menu','records'].includes(ui.view)&&(!battle||battle.done))render();return;}if(e.key!==REVIEW_SAVE_KEY)return;const repair=()=>{try{preflightMainRuntimeRaw(e.newValue);preflightMainRuntimeRaw(readGuardedMain(localStorage,REVIEW_SAVE_KEY));preserveIncomingMain(localStorage,REVIEW_SAVE_KEY,e.newValue);const raw=recoverGuardedMain(localStorage,REVIEW_SAVE_KEY);if(raw!==persistedRaw){storageBlocked=true;paused=true;toast('別の画面の更新があります。再読込して最新の記録を確認してください。');}else toast('以前の画面からの別の記録も保管しました。現在の進行は保護されています。');}catch{storageBlocked=true;paused=true;toast('別の記録を保管できないため保存を止めています。記録は消していません。');}};if(navigator.locks?.request)navigator.locks.request('world-fighter-main:'+REVIEW_SAVE_KEY,repair).catch(()=>{storageBlocked=true;});else repair();});

window.addEventListener?.('pageshow',()=>{try{preflightMainRuntimeRaw(readGuardedMain(localStorage,REVIEW_SAVE_KEY));if(readGuardedMain(localStorage,REVIEW_SAVE_KEY)!==persistedRaw){paused=true;storageBlocked=true;location.reload?.();return;}}catch{storageBlocked=true;return;}if(state&&['home','menu','records'].includes(ui.view)&&(!battle||battle.done))render();});

function runtimeHideGuard(){paused=true;try{const raw=readGuardedMain(localStorage,REVIEW_SAVE_KEY);preflightMainRuntimeRaw(raw);if(raw!==persistedRaw)storageBlocked=true;}catch{storageBlocked=true;}}
window.addEventListener?.('pagehide',runtimeHideGuard);
window.addEventListener?.('visibilitychange',()=>{if(document.hidden)runtimeHideGuard();});

// Fixed home-entry intents only. The original app still owns save admission,
// migration, locks, battle restoration and reset confirmation. No automatic fight.
{const intent=new URLSearchParams(location.search).get('entry');const views=new Set(['hub','abilities','local-training','records','equipment','world','menu','tournament']);if(!storageBlocked&&!battle&&!demo&&!tutorialActive(state)){if(state&&state.abilities.confirmed&&views.has(intent))go(intent,{},true);else if(!state&&intent==='new')go('start-japan',{},true);else if(state&&intent==='reset'){resetOpen=true;renderReset();}}}
